1	<?php
2	
3	namespace App\Services\Stripe;
4	
5	use App\Jobs\Stripe\ExecuteCommissionPayoutJob;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Retail\BrandStoreSettings;
8	use App\Models\Retail\CommissionLedgerEntry;
9	use App\Models\Retail\CommissionPayout;
10	use App\Models\Retail\CommissionPayoutItem;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\ApiConnectionException;
14	use Stripe\Exception\ApiErrorException;
15	use Stripe\Exception\RateLimitException;
16	use Stripe\StripeClient;
17	
18	// V2: Core. Processes eligible commission payouts with hybrid funding (wallet balance first, card charge for shortfall). Transfers net amount to affiliate via Stripe Connect (80/20 split).
19	class CommissionPayoutService
20	{
21	    private StripeClient $stripe;
22	
23	    private float $platformFeePercent;
24	
25	    private int $systemHoldDays;
26	
27	    private int $minHoldDays;
28	
29	    private int $gracePeriodDays;
30	
31	    public function __construct(?StripeClient $stripe = null)
32	    {
33	        $this->stripe = $stripe ?? new StripeClient(config('services.stripe.secret_key'));
34	        $this->platformFeePercent = config('sidest.store.platform_fee_percent', 3);
35	        $this->systemHoldDays = max(0, (int) config('sidest.store.payout_hold_days', 7));
36	        $this->minHoldDays = (int) config('sidest.store.min_payout_hold_days', 7);
37	        // Clamp to [1, 365] — values outside this range produce nonsensical void_at timestamps.
38	        $this->gracePeriodDays = max(1, min(365, (int) config('sidest.store.grace_period_days', 60)));
39	    }
40	
41	    /**
42	     * Main entry point: find all eligible unpaid commissions, batch them,
43	     * and dispatch a per-payout job for each. Returns dispatch counts only —
44	     * actual results are reported per-job via Horizon.
45	     *
46	     * @return array{batches_dispatched: int, batches_created: int, batches_requeued: int}
47	     */
48	    public function processEligiblePayouts(): array
49	    {
50	        $stats = [
51	            'batches_dispatched' => 0,
52	            'batches_created' => 0,
53	            'batches_requeued' => 0,
54	        ];
55	
56	        // Re-dispatch any in-flight batches. ExecuteCommissionPayoutJob's idempotent
57	        // resume logic handles collecting/transferring states safely.
58	        $existingPending = CommissionPayout::query()
59	            ->whereIn('status', ['pending', 'pending_funds', 'collecting', 'transferring'])
60	            ->whereNull('processed_at')
61	            ->where('eligible_after', '<=', now())
62	            ->orderBy('eligible_after')
63	            ->limit(500)
64	            ->get();
65	
66	        foreach ($existingPending as $pendingPayout) {
67	            ExecuteCommissionPayoutJob::dispatch($pendingPayout->id);
68	            $stats['batches_dispatched']++;
69	            $stats['batches_requeued']++;
70	        }
71	
72	        // Find all brands that have unpaid approved accruals, then apply
73	        // per-brand hold days to determine which entries are eligible.
74	        $brandIds = CommissionLedgerEntry::query()
75	            ->whereNull('payout_id')
76	            ->where('entry_type', 'accrual')
77	            ->where('status', 'approved')
78	            ->distinct()
79	            ->pluck('brand_professional_id');
80	
81	        // Pre-load brand store settings for hold-day lookups.
82	        $brandSettings = BrandStoreSettings::query()
83	            ->whereIn('professional_id', $brandIds)
84	            ->pluck('payout_hold_days', 'professional_id');
85	
86	        foreach ($brandIds as $brandId) {
87	            $holdDays = $this->resolveHoldDays($brandSettings[$brandId] ?? null);
88	            $cutoff = now()->utc()->subDays($holdDays);
89	
90	            $groups = CommissionLedgerEntry::query()
91	                ->whereNull('payout_id')
92	                ->where('entry_type', 'accrual')
93	                ->where('status', 'approved')
94	                ->where('brand_professional_id', $brandId)
95	                ->where('occurred_at', '<=', $cutoff)
96	                ->select([
97	                    'brand_professional_id',
98	                    'affiliate_professional_id',
99	                    'currency_code',
100	                    DB::raw('SUM(amount_cents) as total_cents'),
101	                    DB::raw('COUNT(*) as entry_count'),
102	                ])
103	                ->groupBy('brand_professional_id', 'affiliate_professional_id', 'currency_code')
104	                ->having(DB::raw('SUM(amount_cents)'), '>', 0)
105	                ->get();
106	
107	            foreach ($groups as $group) {
108	                try {
109	                    $payout = $this->createPayoutBatch(
110	                        $group->brand_professional_id,
111	                        $group->affiliate_professional_id,
112	                        $group->currency_code,
113	                        $cutoff,
114	                    );
115	
116	                    if (! $payout) {
117	                        continue;
118	                    }
119	
120	                    $stats['batches_created']++;
121	                    ExecuteCommissionPayoutJob::dispatch($payout->id);
122	                    $stats['batches_dispatched']++;
123	                } catch (\Throwable $e) {
124	                    Log::error('Commission payout batch creation failed', [
125	                        'brand_id' => $group->brand_professional_id,
126	                        'affiliate_id' => $group->affiliate_professional_id,
127	                        'currency' => $group->currency_code,
128	                        'error' => $e instanceof ApiErrorException ? ($e->getStripeCode() ?? 'stripe_error') : get_class($e),
129	                    ]);
130	                }
131	            }
132	        }
133	
134	        return $stats;
135	    }
136	
137	    /**
138	     * Resolve the effective hold days for a brand.
139	     * Uses brand override if set, otherwise system default. Always >= system minimum.
140	     */
141	    private function resolveHoldDays(?int $brandPayoutHoldDays): int
142	    {
143	        $days = $brandPayoutHoldDays ?? $this->systemHoldDays;
144	
145	        return max($this->minHoldDays, $days);
146	    }
147	
148	    /**
149	     * Create a payout batch record and link all eligible ledger entries.
150	     */
151	    private function createPayoutBatch(
152	        string $brandId,
153	        string $affiliateId,
154	        string $currency,
155	        \DateTimeInterface $cutoff,
156	    ): ?CommissionPayout {
157	        // READ COMMITTED (PG default) — lockForUpdate() on both reads is sufficient
158	        // to prevent a concurrent batch from claiming the same ledger entries.
159	        return DB::transaction(function () use ($brandId, $affiliateId, $currency, $cutoff) {
160	            $entries = CommissionLedgerEntry::query()
161	                ->whereNull('payout_id')
162	                ->where('entry_type', 'accrual')
163	                ->where('status', 'approved')
164	                ->where('brand_professional_id', $brandId)
165	                ->where('affiliate_professional_id', $affiliateId)
166	                ->where('currency_code', $currency)
167	                ->where('occurred_at', '<=', $cutoff)
168	                ->lockForUpdate()
169	                ->get();
170	
171	            if ($entries->isEmpty()) {
172	                return null;
173	            }
174	
175	            $grossCents = $entries->sum('amount_cents');
176	            if ($grossCents <= 0) {
177	                return null;
178	            }
179	
180	            // Single locked fetch — reused for both the net-commission sum
181	            // below and the foreach that links these entries to the payout.
182	            // lockForUpdate matches the accrual fetch above and closes the
183	            // race where a reversal could land between SUM and GET.
184	            $reversals = CommissionLedgerEntry::query()
185	                ->whereNull('payout_id')
186	                ->where('entry_type', 'reversal')
187	                ->where('status', 'approved')
188	                ->where('brand_professional_id', $brandId)
189	                ->where('affiliate_professional_id', $affiliateId)
190	                ->where('currency_code', $currency)
191	                ->where('occurred_at', '<=', $cutoff)
192	                ->lockForUpdate()
193	                ->get();
194	
195	            $reversalCents = (int) $reversals->sum('amount_cents');
196	            $netCommission = $grossCents + $reversalCents;
197	            if ($netCommission <= 0) {
198	                return null;
199	            }
200	
201	            $platformFeeCents = (int) round($netCommission * $this->platformFeePercent / 100);
202	            $netPayoutCents = $netCommission - $platformFeeCents;
203	
204	            if ($netPayoutCents <= 0) {
205	                return null;
206	            }
207	
208	            // Per-payout grace window — 60d from creation. If the affiliate
209	            // hasn't activated Stripe Connect by then, VoidExpiredPayoutsJob
210	            // cancels this payout and voids its ledger entries.
211	            // grace_period_days lives in config/sidest.php so ops can tune
212	            // the policy without a code release.
213	            $payout = CommissionPayout::forceCreate([
214	                'brand_professional_id' => $brandId,
215	                'affiliate_professional_id' => $affiliateId,
216	                'status' => 'pending',
217	                'gross_commission_cents' => $netCommission,
218	                'platform_fee_cents' => $platformFeeCents,
219	                'net_payout_cents' => $netPayoutCents,
220	                'currency_code' => strtoupper($currency),
221	                'ledger_entry_count' => $entries->count(),
222	                'eligible_after' => $cutoff,
223	                'void_at' => DB::raw("NOW() + INTERVAL '{$this->gracePeriodDays} days'"),
224	                'funding_source' => null,
225	            ]);
226	
227	            foreach ($entries as $entry) {
228	                CommissionPayoutItem::create([
229	                    'payout_id' => $payout->id,
230	                    'commission_ledger_entry_id' => $entry->id,
231	                    'amount_cents' => $entry->amount_cents,
232	                ]);
233	                $entry->forceFill(['payout_id' => $payout->id])->save();
234	            }
235	
236	            foreach ($reversals as $reversal) {
237	                CommissionPayoutItem::create([
238	                    'payout_id' => $payout->id,
239	                    'commission_ledger_entry_id' => $reversal->id,
240	                    'amount_cents' => $reversal->amount_cents,
241	                ]);
242	                $reversal->forceFill(['payout_id' => $payout->id])->save();
243	            }
244	
245	            return $payout;
246	        });
247	    }
248	
249	    /**
250	     * Process a single payout through the full 3-step flow with idempotent resume:
251	     *   1) Debit wallet balance (atomic with status update — crash-safe).
252	     *   2) Charge brand's card for any shortfall.
253	     *   3) Transfer net amount to affiliate via Stripe Connect.
254	     *
255	     * Each step checks the payout's current status before executing, so retries
256	     * (both Horizon automatic and admin manual) resume from where they left off
257	     * rather than restarting from scratch. This prevents double-debiting the wallet
258	     * and double-charging the brand's card.
259	     *
260	     * Return values:
261	     * - true:  completed
262	     * - null:  pending for funding/retry
263	     * - false: failed
264	     */
265	    public function processPayoutBatch(CommissionPayout $payout): ?bool
266	    {
267	        if ($payout->status === 'completed') {
268	            return true;
269	        }
270	
271	        $brand = Professional::find($payout->brand_professional_id);
272	        $affiliate = Professional::find($payout->affiliate_professional_id);
273	
274	        if (! $affiliate?->stripe_connect_account_id || $affiliate->stripe_connect_status !== 'active') {
275	            $this->markPendingFunding($payout, 'affiliate_not_connected', 'Affiliate Stripe Connect account is not active — holding for grace period');
276	
277	            return null;
278	        }
279	
280	        if (! $brand) {
281	            $this->failPayout($payout, 'brand_missing', 'Brand account was not found.');
282	
283	            return false;
284	        }
285	
286	        if (! $brand->stripe_customer_id || ! $brand->stripe_payment_method_id) {
287	            $this->markPendingFunding(
288	                $payout,
289	                'brand_payment_method_missing',
290	                'No payment method on file. Please add a card in your Stripe settings.',
291	            );
292	
293	            return null;
294	        }
295	
296	        $currencyUpper = strtoupper($payout->currency_code);
297	        $currencyLower = strtolower($currencyUpper);
298	        $amountToCollect = $payout->gross_commission_cents;
299	
300	        // Idempotency key suffix — retry_count is incremented on each admin manual retry
301	        // so fresh Stripe objects are created rather than returning a refunded/failed one
302	        // from within the 24-hour idempotency TTL window.
303	        $retryKey = '_r'.$payout->retry_count;
304	
305	        // Step 1: Wallet debit — or resume from recorded state
306	        //
307	        // The debit and the status update are wrapped in a single DB::transaction
308	        // so a process crash between them can't leave the wallet reduced but the
309	        // payout record still showing 'pending' (which would cause a double-debit on retry).
310	        $walletDebitCents = 0;
311	        $chargeAmountCents = $amountToCollect;
312	
313	        if (in_array($payout->status, ['collecting', 'collected', 'transferring'], true)) {
314	            // Wallet debit already committed in a previous run — read from DB, don't re-debit.
315	            $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
316	            $chargeAmountCents = (int) ($payout->charge_cents ?? $amountToCollect);
317	        } else {
318	            // READ COMMITTED (PG default) — the payout status update and wallet debit
319	            // are atomic here; lockForUpdate() inside debitBrandManualBalancePartial
320	            // guards against concurrent debits on the wallet row itself.
321	            DB::transaction(function () use ($payout, $brand, $amountToCollect, $currencyUpper, &$walletDebitCents, &$chargeAmountCents): void {
322	                $walletDebitCents = $this->debitBrandManualBalancePartial($brand->id, $amountToCollect, $currencyUpper);
323	                $chargeAmountCents = $amountToCollect - $walletDebitCents;
324	
325	                $fundingSource = 'card';
326	                if ($walletDebitCents > 0 && $chargeAmountCents > 0) {
327	                    $fundingSource = 'wallet_and_card';
328	                } elseif ($walletDebitCents > 0) {
329	                    $fundingSource = 'wallet';
330	                }
331	
332	                $payout->forceFill([
333	                    'status' => 'collecting',
334	                    'funding_source' => $fundingSource,
335	                    'wallet_debit_cents' => $walletDebitCents,
336	                    'charge_cents' => $chargeAmountCents,
337	                    'failure_code' => null,
338	                    'failure_reason' => null,
339	                ])->save();
340	            });
341	        }
342	
343	        // Step 2: Charge brand's card for the shortfall (if any)
344	        $latestChargeId = null;
345	
346	        if (in_array($payout->status, ['collected', 'transferring'], true)) {
347	            // PaymentIntent already succeeded in a previous run.
348	            // Retrieve the charge ID so we can use source_transaction on the transfer.
349	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
350	                $pi = $this->stripe->paymentIntents->retrieve($payout->stripe_payment_intent_id);
351	                $latestChargeId = $this->extractLatestChargeId($pi);
352	            }
353	        } elseif ($chargeAmountCents > 0) {
354	            try {
355	                $paymentIntent = $this->stripe->paymentIntents->create([
356	                    'amount' => $chargeAmountCents,
357	                    'currency' => $currencyLower,
358	                    'customer' => $brand->stripe_customer_id,
359	                    'payment_method' => $brand->stripe_payment_method_id,
360	                    'confirm' => true,
361	                    'off_session' => true,
362	                    'description' => "Commission payout #{$payout->id}",
363	                    'metadata' => [
364	                        'sidest_payout_id' => $payout->id,
365	                        'brand_id' => $brand->id,
366	                        'affiliate_id' => $affiliate->id,
367	                    ],
368	                ], ['idempotency_key' => 'pi_'.$payout->id.$retryKey]);
369	
370	                if ($paymentIntent->status !== 'succeeded') {
371	                    // SCA required — cancel the PI so the idempotency key is freed for the next
372	                    // attempt. Without cancellation the same key returns this stuck PI for 24h.
373	                    try {
374	                        $this->stripe->paymentIntents->cancel($paymentIntent->id);
375	                    } catch (\Throwable) {
376	                        // Non-critical: PI may already be in a terminal state
377	                    }
378	                    if ($walletDebitCents > 0) {
379	                        $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
380	                    }
381	                    $this->markPendingFunding($payout, 'charge_requires_action', 'Card charge requires authentication.');
382	
383	                    return null;
384	                }
385	
386	                $latestChargeId = $this->extractLatestChargeId($paymentIntent);
387	
388	                $payout->forceFill([
389	                    'stripe_payment_intent_id' => $paymentIntent->id,
390	                    'status' => 'collected',
391	                ])->save();
392	            } catch (ApiConnectionException|RateLimitException $e) {
393	                // Transient error — re-throw so Horizon retries with backoff.
394	                // Wallet debit is already committed in 'collecting' status; the
395	                // idempotent resume will skip re-debiting on the next attempt.
396	                throw $e;
397	            } catch (ApiErrorException $e) {
398	                // Terminal card failure (declined, invalid PM, SCA permanently blocked, etc.)
399	                if ($walletDebitCents > 0) {
400	                    $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
401	                }
402	                $this->markPendingFunding($payout, 'charge_failed', $e->getStripeCode() ?? 'stripe_error');
403	
404	                return null;
405	            }
406	        } else {
407	            // Fully funded by wallet — only advance status if not already past this step
408	            if (! in_array($payout->status, ['collected', 'transferring'], true)) {
409	                $payout->forceFill(['status' => 'collected'])->save();
410	            }
411	        }
412	
413	        // Step 3: Transfer net amount to the affiliate's Connect account
414	        try {
415	            if ($payout->status !== 'transferring') {
416	                $payout->forceFill(['status' => 'transferring'])->save();
417	            }
418	
419	            $transferPayload = [
420	                'amount' => $payout->net_payout_cents,
421	                'currency' => $currencyLower,
422	                'destination' => $affiliate->stripe_connect_account_id,
423	                'description' => "Commission payout #{$payout->id} to {$affiliate->display_name}",
424	                'metadata' => [
425	                    'sidest_payout_id' => $payout->id,
426	                    'brand_id' => $brand->id,
427	                    'affiliate_id' => $affiliate->id,
428	                ],
429	            ];
430	
431	            if ($latestChargeId) {
432	                $transferPayload['source_transaction'] = $latestChargeId;
433	            }
434	
435	            $transfer = $this->stripe->transfers->create(
436	                $transferPayload,
437	                ['idempotency_key' => 'tr_'.$payout->id.$retryKey]
438	            );
439	
440	            $payout->forceFill([
441	                'stripe_transfer_id' => $transfer->id,
442	                'status' => 'completed',
443	                'processed_at' => now(),
444	                'failure_code' => null,
445	                'failure_reason' => null,
446	            ])->save();
447	
448	            Log::info('Commission payout completed', [
449	                'payout_id' => $payout->id,
450	                'gross_cents' => $payout->gross_commission_cents,
451	                'wallet_debit_cents' => $walletDebitCents,
452	                'charge_cents' => $chargeAmountCents,
453	                'platform_fee_cents' => $payout->platform_fee_cents,
454	                'net_cents' => $payout->net_payout_cents,
455	                'funding_source' => $payout->funding_source,
456	                'currency' => $payout->currency_code,
457	            ]);
458	
459	            // Rebuild commerce aggregates so commission_paid_cents is reflected.
460	            // Guard against null FKs (SET NULL on professional hard-delete).
461	            if ($payout->brand_professional_id && $payout->affiliate_professional_id) {
462	                \App\Jobs\Analytics\RebuildCommerceDailyAggregatesJob::dispatch(
463	                    (string) $payout->brand_professional_id,
464	                    (string) $payout->affiliate_professional_id,
465	                    now()->toDateString()
466	                );
467	            }
468	
469	            return true;
470	        } catch (ApiConnectionException|RateLimitException $e) {
471	            // Transient error — re-throw so Horizon retries from 'transferring' status.
472	            // Wallet and charge are NOT reversed: if the transfer succeeded on Stripe's side
473	            // but the response was lost in transit, the idempotency key returns the same
474	            // transfer on retry rather than creating a duplicate.
475	            throw $e;
476	        } catch (ApiErrorException $e) {
477	            // Terminal transfer failure — credit wallet back, then attempt to auto-refund.
478	            if ($walletDebitCents > 0) {
479	                $this->creditBrandManualBalance($brand->id, $walletDebitCents, $currencyUpper);
480	            }
481	
482	            $failureCode = 'transfer_failed';
483	
484	            if ($payout->stripe_payment_intent_id && $chargeAmountCents > 0) {
485	                try {
486	                    $this->stripe->refunds->create([
487	                        'payment_intent' => $payout->stripe_payment_intent_id,
488	                    ], ['idempotency_key' => "rf_{$payout->id}_{$payout->stripe_payment_intent_id}"]);
489	                    $failureCode = 'transfer_failed_refunded';
490	                    // Clear PI ID so an admin retry can create a fresh PaymentIntent
491	                    // (same idempotency key within 24h would return the now-refunded PI).
492	                    $payout->forceFill(['stripe_payment_intent_id' => null])->save();
493	                } catch (\Throwable $refundEx) {
494	                    // Auto-refund failed — the brand may still be charged. Flag for manual resolution.
495	                    $failureCode = 'transfer_failed_refund_needed';
496	                    $payout->forceFill(['needs_manual_refund' => true])->save();
497	                    Log::error('Auto-refund after transfer failure failed — manual action required', [
498	                        'payout_id' => $payout->id,
499	                        'payment_intent_id' => $payout->stripe_payment_intent_id,
500	                        'transfer_error' => $e->getStripeCode() ?? 'stripe_error',
501	                        'refund_error' => $refundEx instanceof ApiErrorException ? ($refundEx->getStripeCode() ?? 'stripe_error') : get_class($refundEx),
502	                    ]);
503	                }
504	            }
505	
506	            $this->failPayout($payout, $failureCode, $e->getStripeCode() ?? 'stripe_error');
507	
508	            return false;
509	        }
510	    }
