512	    /**
513	     * Debit the brand's wallet balance, up to the requested amount (partial OK).
514	     * Returns the actual amount debited (0 if no balance available).
515	     */
516	    private function debitBrandManualBalancePartial(string $brandId, int $requestedCents, string $currencyCode): int
517	    {
518	        if ($requestedCents <= 0) {
519	            return 0;
520	        }
521	
522	        // READ COMMITTED (PG default) — lockForUpdate() on the professional row
523	        // serialises concurrent debits; no higher isolation level is required.
524	        return DB::transaction(function () use ($brandId, $requestedCents, $currencyCode) {
525	            $brand = Professional::query()
526	                ->whereKey($brandId)
527	                ->lockForUpdate()
528	                ->first();
529	
530	            if (! $brand) {
531	                return 0;
532	            }
533	
534	            $balance = max(0, (int) ($brand->stripe_manual_balance_cents ?? 0));
535	            $walletCurrency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
536	
537	            if ($walletCurrency !== strtoupper($currencyCode) || $balance <= 0) {
538	                return 0;
539	            }
540	
541	            $debit = min($balance, $requestedCents);
542	            $brand->stripe_manual_balance_cents = $balance - $debit;
543	            $brand->save();
544	
545	            return $debit;
546	        });
547	    }
548	
549	    public function creditBrandManualBalance(string $brandId, int $amountCents, string $currencyCode): void
550	    {
551	        if ($amountCents <= 0) {
552	            return;
553	        }
554	
555	        // READ COMMITTED (PG default) — lockForUpdate() serialises concurrent credits.
556	        DB::transaction(function () use ($brandId, $amountCents, $currencyCode) {
557	            $brand = Professional::query()
558	                ->whereKey($brandId)
559	                ->lockForUpdate()
560	                ->first();
561	
562	            if (! $brand) {
563	                return;
564	            }
565	
566	            $balance = (int) ($brand->stripe_manual_balance_cents ?? 0);
567	            $brand->stripe_manual_balance_cents = $balance + $amountCents;
568	            $brand->stripe_manual_balance_currency = strtoupper((string) ($brand->stripe_manual_balance_currency ?: $currencyCode));
569	            $brand->save();
570	        });
571	    }
572	
573	    private function extractLatestChargeId(object $paymentIntent): ?string
574	    {
575	        if (is_string($paymentIntent->latest_charge ?? null) && $paymentIntent->latest_charge !== '') {
576	            return $paymentIntent->latest_charge;
577	        }
578	
579	        if (is_object($paymentIntent->latest_charge ?? null) && is_string($paymentIntent->latest_charge->id ?? null)) {
580	            return $paymentIntent->latest_charge->id;
581	        }
582	
583	        if (is_object($paymentIntent->charges ?? null) && is_array($paymentIntent->charges->data ?? null)) {
584	            foreach ($paymentIntent->charges->data as $charge) {
585	                if (is_object($charge) && is_string($charge->id ?? null) && $charge->id !== '') {
586	                    return $charge->id;
587	                }
588	            }
589	        }
590	
591	        return null;
592	    }
593	
594	    private function markPendingFunding(CommissionPayout $payout, string $code, string $reason): void
595	    {
596	        $payout->forceFill([
597	            'status' => 'pending_funds',
598	            'failure_code' => $code,
599	            'failure_reason' => $reason,
600	            'processed_at' => null,
601	        ])->save();
602	
603	        Log::notice('Commission payout pending funding', [
604	            'payout_id' => $payout->id,
605	            'code' => $code,
606	            'reason' => $reason,
607	        ]);
608	    }
609	
610	    private function failPayout(CommissionPayout $payout, string $code, string $reason): void
611	    {
612	        $payout->forceFill([
613	            'status' => 'failed',
614	            'failure_code' => $code,
615	            'failure_reason' => $reason,
616	        ])->save();
617	
618	        Log::warning('Commission payout failed', [
619	            'payout_id' => $payout->id,
620	            'code' => $code,
621	            'reason' => $reason,
622	        ]);
623	    }
624	
625	    /**
626	     * Manually retry a stuck payout batch (admin endpoint).
627	     *
628	     * Increments retry_count so a fresh Stripe idempotency key is used —
629	     * prevents Stripe returning a refunded/failed PI from within the 24h TTL window.
630	     *
631	     * Blocked for transfer_failed_refund_needed: the auto-refund itself failed, so
632	     * the brand may still be charged. Manual verification is required before retrying.
633	     *
634	     * Runs synchronously so the admin sees the result immediately.
635	     */
636	    public function retryPayout(CommissionPayout $payout): bool
637	    {
638	        if (! in_array($payout->status, ['failed', 'pending', 'pending_funds'], true)) {
639	            return false;
640	        }
641	
642	        // Auto-refund failed — manual verification required before retrying to avoid double-charging.
643	        if ($payout->failure_code === 'transfer_failed_refund_needed') {
644	            return false;
645	        }
646	
647	        // If the wallet was already debited in a previous run, resume from 'collecting'
648	        // so processPayoutBatch() enters its idempotent resume branch and skips
649	        // re-debiting. Resetting to 'pending' would bypass that branch and double-debit.
650	        $resumeStatus = ((int) ($payout->wallet_debit_cents ?? 0)) > 0 ? 'collecting' : 'pending';
651	
652	        $payout->forceFill([
653	            'status' => $resumeStatus,
654	            'failure_code' => null,
655	            'failure_reason' => null,
656	            'needs_manual_refund' => false,
657	            'retry_count' => ($payout->retry_count ?? 0) + 1,
658	        ])->save();
659	
660	        return $this->processPayoutBatch($payout) === true;
661	    }
662	
663	    /**
664	     * Get payout summary for a professional (as brand or affiliate).
665	     */
666	    public function getPayoutSummary(Professional $professional): array
667	    {
668	        $asBrand = CommissionPayout::query()
669	            ->where('brand_professional_id', $professional->id)
670	            ->selectRaw('status, COUNT(*) as count, SUM(gross_commission_cents) as total_cents')
671	            ->groupBy('status')
672	            ->get()
673	            ->keyBy('status');
674	
675	        $asAffiliate = CommissionPayout::query()
676	            ->where('affiliate_professional_id', $professional->id)
677	            ->selectRaw('status, COUNT(*) as count, SUM(net_payout_cents) as total_cents')
678	            ->groupBy('status')
679	            ->get()
680	            ->keyBy('status');
681	
682	        return [
683	            'as_brand' => $asBrand,
684	            'as_affiliate' => $asAffiliate,
685	        ];
686	    }
687	}
