3	namespace App\Jobs\Stripe;
4	
5	use App\Models\Retail\CommissionPayout;
6	use App\Services\Stripe\CommissionPayoutService;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldBeUnique;
9	use Illuminate\Contracts\Queue\ShouldQueue;
10	use Illuminate\Foundation\Bus\Dispatchable;
11	use Illuminate\Queue\InteractsWithQueue;
12	use Illuminate\Queue\SerializesModels;
13	use Illuminate\Support\Facades\Log;
14	
15	// V2: Core. Processes a single commission payout (wallet debit → card charge → Stripe transfer).
16	// Dispatched by ProcessCommissionPayoutsJob for each eligible payout batch.
17	// Idempotent: processPayoutBatch resumes from the payout's current status so Horizon retries are safe.
18	// ShouldBeUnique prevents two workers racing on the same payout if the daily cron re-dispatches
19	// a job that is already queued or processing (e.g. waiting on a backoff delay).
20	class ExecuteCommissionPayoutJob implements ShouldBeUnique, ShouldQueue
21	{
22	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
23	
24	    public int $tries = 5;
25	
26	    public int $timeout = 120;
27	
28	    // Uniqueness lock TTL — slightly longer than timeout so the lock outlives the job.
29	    public int $uniqueFor = 180;
30	
31	    /**
32	     * Backoff between Horizon retries in seconds.
33	     * Gives Stripe time to recover from transient outages between attempts.
34	     */
35	    public function backoff(): array
36	    {
37	        return [60, 120, 300, 600];
38	    }
39	
40	    public function __construct(public readonly string $payoutId)
41	    {
42	        $this->onQueue('stripe');
43	    }
44	
45	    public function uniqueId(): string
46	    {
47	        return $this->payoutId;
48	    }
49	
50	    public function handle(CommissionPayoutService $payoutService): void
51	    {
52	        $payout = CommissionPayout::find($this->payoutId);
53	
54	        if (! $payout || $payout->status === 'completed') {
55	            return;
56	        }
57	
58	        $start = microtime(true);
59	        $payoutService->processPayoutBatch($payout);
60	        $durationMs = (int) round((microtime(true) - $start) * 1000);
61	
62	        // Alert threshold: 30s = 25% of job timeout. Nightwatch captures warning+
63	        // level logs — configure an alert on this message to catch batches trending
64	        // toward the 120s timeout before they start failing.
65	        if ($durationMs > 30_000) {
66	            Log::warning('ExecuteCommissionPayoutJob slow payout batch', [
67	                'payout_id' => $this->payoutId,
68	                'duration_ms' => $durationMs,
69	                'attempt' => $this->attempts(),
70	            ]);
71	        } else {
72	            Log::info('ExecuteCommissionPayoutJob completed', [
73	                'payout_id' => $this->payoutId,
74	                'duration_ms' => $durationMs,
75	            ]);
76	        }
77	    }
78	
79	    public function failed(\Throwable $e): void
80	    {
81	        // Forward to Nightwatch so this payout failure is observable by payout_id
82	        // as a named exception, not a generic "queue job failed" event.
83	        // Log::error gives a structured breadcrumb in cloud logs even if Nightwatch
84	        // is offline.
85	        report($e);
86	
87	        Log::error('ExecuteCommissionPayoutJob exhausted all retries', [
88	            'payout_id' => $this->payoutId,
89	            'error' => $e->getMessage(),
90	        ]);
91	
92	        $payout = CommissionPayout::find($this->payoutId);
93	        if (! $payout || in_array($payout->status, ['completed', 'failed'], true)) {
94	            return;
95	        }
96	
97	        $walletDebitCents = (int) ($payout->wallet_debit_cents ?? 0);
98	        $failureReason = 'Payout job exhausted all Horizon retries after transient errors. '
99	            .$e->getMessage();
100	        $updates = ['status' => 'failed', 'failure_code' => 'job_exhausted'];
101	
102	        // If retries exhausted while still in 'collecting', the PaymentIntent was never
103	        // successfully created — there is no charge to match the wallet debit. Reverse it
104	        // automatically so the brand's balance is correct without manual intervention.
105	        // Also clear wallet_debit_cents so retryPayout() starts a fresh debit rather than
106	        // resuming from 'collecting' (which would skip the debit against a restored balance).
107	        if ($payout->status === 'collecting' && $walletDebitCents > 0) {
108	            app(CommissionPayoutService::class)->creditBrandManualBalance(
109	                (string) $payout->brand_professional_id,
110	                $walletDebitCents,
111	                strtoupper((string) $payout->currency_code)
112	            );
113	            $updates['wallet_debit_cents'] = 0;
114	            $failureReason = 'Payout job exhausted all retries — wallet debit of '
115	                .$walletDebitCents.' cents reversed automatically. '
116	                .$e->getMessage();
117	
118	            Log::notice('ExecuteCommissionPayoutJob reversed wallet debit after retry exhaustion', [
119	                'payout_id' => $this->payoutId,
120	                'reversed_cents' => $walletDebitCents,
121	            ]);
122	        }
123	
124	        $payout->forceFill(array_merge($updates, ['failure_reason' => $failureReason]))->save();
125	    }
126	}
