132	/**
133	 * Build a Mockery StripeClient mock wired with per-service sub-mocks.
134	 * StripeClient::__get delegates to getService(), so we mock getService() —
135	 * that is the actual method Mockery intercepts when $stripe->paymentIntents is accessed.
136	 */
137	function payoutSvc_makeStripe(array $services = []): StripeClient
138	{
139	    $piMock = $services['pi'] ?? Mockery::mock();
140	    $transferMock = $services['transfer'] ?? Mockery::mock();
141	    $refundMock = $services['refund'] ?? Mockery::mock();
142	
143	    $stripe = Mockery::mock(StripeClient::class);
144	    $stripe->shouldReceive('getService')->with('paymentIntents')->andReturn($piMock);
145	    $stripe->shouldReceive('getService')->with('transfers')->andReturn($transferMock);
146	    $stripe->shouldReceive('getService')->with('refunds')->andReturn($refundMock);
147	
148	    return $stripe;
149	}
